    return <main><header><small>ONLYSTUDIES</small><h1>Make difficult ideas<br />feel visual.</h1><p>Generate animated lessons with a clear explanation, analogy, and worked example.</p></header><section><form onSubmit={create}><label>What should we explain?<input required minLength={2} value={topic} onChange={e => setTopic(e.target.value)} placeholder="e.g. Newton's third law" /></label><div className="grid"><label>Subject<select value={subject} onChange={e => setSubject(e.target.value)}>{subjects.map(x => <option key={x}>{x}</option>)}</select></label><label>Quality<select value={quality} onChange={e => setQuality(e.target.value)}>{["Low", "Medium", "High"].map(x => <option key={x}>{x}</option>)}</select></label><label>Voice<select disabled={!voiceover} value={voice} onChange={e => setVoice(e.target.value)}>{["teaching_assistant", "professor", "enthusiastic", "calm", "neutral"].map(x => <option key={x}>{x.replace("_", " ")}</option>)}</select></label></div><label className="toggle"><input type="checkbox" checked={voiceover} onChange={e => setVoiceover(e.target.checked)} />Include voiceover</label><button disabled={working}>{working ? "Creating lesson…" : "Generate lesson"}</button></form></section>{job && <section><strong className={job.status}>{job.status === "completed" ? "Lesson ready" : `Status: ${job.status}`}</strong>{job.error && <pre>{job.error}</pre>}{job.status === "completed" && <><video controls src={`${API}${job.video_url}`} /><a href={`${API}${job.video_url}`}>Download MP4</a><label>Improve this lesson<textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="For example: slow down the worked example." /></label><button onClick={regenerate}>Regenerate with feedback</button></>}</section>}</main>
}
